#include <iostream>
using namespace std;
​
int main() {
    string s;
    cin >> s;
​
    string num = "";  // 存储数字部分
    string res = "";  // 存储解压后的结果
​
    for (char c : s) {
        // 非小写字母或数字，直接报错
        if (!isdigit(c) && (c < 'a' || c > 'z')) {
            cout << "!error" << endl;
            return 0;
        }
​
        if (isdigit(c)) {
            num += c;  // 记录数字
        } else {
            // 解析之前累积的数字
            if (!num.empty()) {
                int repeat = stoi(num);
                if (repeat <= 2) {  // 解压缩要求大于2，否则非法
                    cout << "!error" << endl;
                    return 0;
                }
                res.append(repeat, c);  // 追加字符
                num.clear();  // 重置数字
            } else {
                res += c;  // 直接追加字符
            }
        }
    }
​
    cout << res << endl;
    return 0;
}
