        // 非小写字母或数字，直接报错
        if (!/[0-9a-z]/.test(c)) {
            console.log("!error");
            rl.close();
            return;
        }
​
        if (/\d/.test(c)) {
            num += c; // 记录数字
        } else {
            // 解析之前累积的数字
            if (num !== "") {
                let repeat = parseInt(num, 10);
                if (repeat <= 2) { // 解压缩要求大于2，否则非法
                    console.log("!error");
                    rl.close();
                    return;
                }
                res += c.repeat(repeat); // 追加字符
                num = ""; // 重置数字
            } else {
                res += c; // 直接追加字符
            }
        }
    }
​
    console.log(res);
