package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "unicode"
)
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    if scanner.Scan() {
        s := scanner.Text()
​
        var res string
        var num string
​
        for _, c := range s {
            // 非小写字母或数字，直接报错
            if !unicode.IsDigit(c) && (c < 'a' || c > 'z') {
                fmt.Println("!error")
                return
            }
​
            if unicode.IsDigit(c) {
                num += string(c) // 记录数字
            } else {
                // 解析之前累积的数字
                if num != "" {
                    repeat, _ := strconv.Atoi(num)
                    if repeat <= 2 { // 解压缩要求大于2，否则非法
                        fmt.Println("!error")
                        return
                    }
                    res += repeatChar(c, repeat) // 追加字符
                    num = "" // 清空 num
                } else {
                    res += string(c) // 直接追加字符
                }
            }
        }
​
        fmt.Println(res)
    }
}
​
// repeatChar 生成重复字符的字符串
func repeatChar(c rune, count int) string {
    result := make([]rune, count)
    for i := range result {
        result[i] = c
    }
    return string(result)
}
